def calculate_perimeter(radius, shape='square'):
    if shape == 'square':
        # A square with d_infinity <= radius has side length 2*radius + 1
        # The perimeter is 4 * (2*radius + 1)
        return 4 * (2 * radius + 1)
    elif shape == 'diamond':
        # A diamond with d_1 <= radius has a perimeter of 4 * (radius + 1)
        # Wait, let's re-calculate for radius 1: (0,0), (1,0), (-1,0), (0,1), (0,-1)
        # Its neighbors are (2,0), (1,1), (1,-1), (0,2), (-1,1), (-2,0), (-1,-1), (0,-2)
        # Total 8 neighbors. For radius 2, 12 neighbors.
        # So perimeter is 4 * (radius + 1).
        return 4 * (radius + 1)

for n in range(1, 10):
    p_sq = calculate_perimeter(n, 'square')
    p_dia = calculate_perimeter(n, 'diamond')
    print(f"Turn {n}: Square Perimeter = {p_sq}, Diamond Perimeter = {p_dia}")
